def merge_intervals(intervals):
    if not intervals:
        return []

    # Create a sorted copy of the intervals (by start, then end)
    sorted_intervals = sorted([(s, e) for s, e in intervals], key=lambda x: (x[0], x[1]))

    # Initialize merged list with the first interval
    merged = [[sorted_intervals[0][0], sorted_intervals[0][1]]]]

    # Iterate over the remaining intervals
    for s, e in sorted_intervals[1:]:
        # If the current interval overlaps or touches the last merged interval, merge them
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        # Otherwise, start a new merged interval
        else:
            merged.append([s, e])

    return merged

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    result = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError(f"Invalid weight {weight}")

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            if current_batch:
                result.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        result.append(current_batch)

    return result

import codecs

def parse_sse(chunks):
    decoder = codecs.getincrementaldecoder("utf-8")()
    buffer = ""
    data_parts = []
    results = []
    finished = False

    for chunk in chunks:
        decoded = decoder.decode(chunk, final=False)
        if finished:
            continue
        buffer += decoded

        pos = 0
        while True:
            nl = buffer.find("\n", pos)
            if nl == -1:
                break
            line = buffer[pos:nl]
            if line.endswith("\r"):
                line = line[:-1]
            if line == "":
                # Dispatch event
                if data_parts:
                    event = "\n".join(data_parts)
                    if event == "[DONE]":
                        finished = True
                    else:
                        results.append(event)
                data_parts = []
            else:
                if line.startswith(":"):
                    pass  # comment – skip
                else:
                    if ":" in line:
                        field, value = line.split(":", 1)
                        if field == "data":
                            if value.startswith(" "):
                                value = value[1:]
                            data_parts.append(value)
            pos = nl + 1

        buffer = buffer[pos:]

    return results
